// Assembles the system prompts from prompt/*.md into src/prompt.generated.ts at build time.
// persona.md and facts.md are copied verbatim from the planner's files; do not edit them here.
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { loadRouterInputs } from './router-inputs.mjs';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const read = (name) => readFileSync(join(root, 'prompt', name), 'utf8').trim();

const persona = read('persona.md');
const facts = read('facts.md');
const runtime = read('runtime.md');
const build = read('build.md');

const chatSystem = [persona, '---', facts, '---', runtime].join('\n\n');

// The router (WAVE4 A1): persona rules + facts.md + the scripted intent ids (scripts/router-inputs.mjs).
const router = loadRouterInputs();

const out = `// GENERATED by scripts/gen-prompt.mjs from prompt/*.md. Do not edit by hand.
export const CHAT_SYSTEM_PROMPT = ${JSON.stringify(chatSystem)};
export const BUILD_SYSTEM_PROMPT = ${JSON.stringify(build)};
export const ROUTER_SYSTEM_PROMPT = ${JSON.stringify(router.system)};
export const ROUTER_INTENT_IDS: readonly string[] = ${JSON.stringify(router.intentIds)};
`;
writeFileSync(join(root, 'src', 'prompt.generated.ts'), out);
console.log(`prompt: chat ${chatSystem.length} chars, build ${build.length} chars, router ${router.system.length} chars (${router.intentIds.length} intents)`);
